from pathlib import Path
import re,html,difflib,markdown,json
O=Path(__file__).resolve().parent;R=O.parents[3]
def render(s):return markdown.markdown(re.sub(r'<!--\s*@[^>]*-->','',s),extensions=['extra','sane_lists'])
def image(n,c):return '<figure><a href="'+n+'.png"><img loading="lazy" src="'+n+'.png" alt="'+html.escape(c,quote=True)+'"></a><figcaption>'+c+'</figcaption></figure>'
before=(O/'Color_Nails.before.md').read_text(encoding='utf-8');after=(R/'commons/maps/Color_Nails/final.md').read_text(encoding='utf-8');assert after==(O/'Color_Nails.after.md').read_text(encoding='utf-8')
a=before.split('\n\n');b=after.split('\n\n');pairs=[]
for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
 if tag=='equal':continue
 pairs.append('<div class="pair"><div><h3>Before</h3>'+(render('\n\n'.join(a[i:j])) or '<p>Added encounter passage or shared illustration.</p>')+'</div><div><h3>Now</h3>'+render('\n\n'.join(b[k:l]))+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(O.parent/'2026-09-23-array-molnar-volume/index.html').read_text(encoding='utf-8'),re.S)[1]
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Nails — the choosing hand</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Colour · 23 September 2026</div><h1>The choosing hand.</h1><p class="intro">A colour you left can be found again<br>at the same place.</p><p class="status">Applied to <strong>Color_Nails/final.md</strong>. The working salon is preserved. A small prose revision and a native illustration follow the colour from the coordinate to the body.</p><nav><a href="#encounter">The salon</a><a href="#gesture">One coordinate</a><a href="#comparison">What changed</a><a href="#reading">Read the chapter</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Color_Nails&amp;doc=final">Read and comment</a></nav>'''
page+='<section id="encounter"><h2>A small finish, a monumental hand</h2>'+image('salon-turquoise','The actual museum salon at a selected eye-height camera: two RGB plinths, the manicure table and the giant hand. The petite hand stands on the cushion.')+image('same-choice-two-scales','The same selected colours arrive at two copies of the source hand. These native views are shown at different image scales to make the surfaces readable. The labels give their heights in the hall.')+'<p>The installation already holds the encounter. One point changes the nail materials; the other changes the skin. A coordinate small enough to move by hand reaches a body much larger than the furniture around it.</p></section>'
page+='<section id="gesture"><h2>Return to a colour</h2>'+image('one-channel-two-choices','Native views from the same camera. Red and green stay fixed while the actual RGB point moves along blue. The source mesh, pose and skin value remain unchanged.')+'<p>The same gesture also updates both production VR hand-material receivers. The new check connects the real pickable RGB points to those receivers inside an isolated museum run. It supplies the point movement and omits tracked hand poses; these illustrations show the placed display hands.</p><details><summary>The existing RGB plinth</summary>'+image('rgb-choice','The half-metre RGB volume remains on its open plinth. This is the working interface already present in the hall.')+'</details></section>'
page+='<section id="comparison"><h2>Let the encounter carry the question</h2><p>The opening prediction exercise becomes a short return to a colour’s place. A repeated instruction is removed. The ending follows the unchanged length of a finger instead of asking the reader to list freedoms and limits. One paragraph brings forward the existing critical draft’s bottles, brushwork and absent drying time. The coordinate explanation, material assignment, scale comparison, VR hand invitation and Rainbow handoff remain.</p>'+''.join(pairs)+'<p><a href="Color_Nails.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Companion changes</a></p></section>'
page+='<section id="reading"><article class="reading">'+render(after)+'</article></section>'
page+='''<section id="evidence" class="evidence"><h2>What was checked</h2><p>59 focused assertions pass: actual RGB-point pickup and movement, preview and both display-hand materials, independent skin/nail edits, return to the original colour, unchanged geometry and transforms, and both production player-hand receiver children. Original loaded colours are restored after the run.</p><p>The player-hand scenes are invisible fixtures with their XR pose drivers omitted and animation trees disabled. Their original meshes and receiver children are retained. This verifies the material path, not tracked-controller movement, bare-hand tracking, wearer experience or headset comfort. No walk or performance claim is made. No production source or placement was changed.</p><p>An initial independence assertion compared a repeatedly transformed point against its ideal decimal input. The final check uses the actual selected value immediately before and after the other surface is edited. Both values are recorded; the difference is about 0.0000024 in blue. No production repair was needed.</p><p>Figures crop, resize and label native Godot captures; native and composed views were inspected. No live museum restart, live bake/save overwrite, commit or frozen book/audio rebuild.</p><p><a href="report.json">Runtime record</a> · <a href="source_manifest.json">Capture inputs</a> · <a href="verification.json">Preservation and publication checks</a> · <a href="SUMMARY.md">Findings and decisions</a></p></section><footer>Next: Color_Rainbow — the chosen colour meets a public arrangement and a celebration.</footer></main></body></html>'''
(O/'index.html').write_text(page,encoding='utf-8')
diffs=[]
for relative in json.loads((O/'baseline-hashes.json').read_text()):
 if relative.endswith('/final.md'):continue
 diffs.extend(difflib.unified_diff((O/'before'/relative).read_text(encoding='utf-8').splitlines(True),(R/relative).read_text(encoding='utf-8').splitlines(True),fromfile='before/'+relative,tofile=relative))
(O/'source-changes.diff').write_text(''.join(diffs),encoding='utf-8')
print('Built current reading and original/current comparison.')
